#!/usr/bin/env node
'use strict';
const fs = require('node:fs');
const file = process.argv[2];
const fail = reasons => ({ status: 'BLOCKED', reasons });
if (!file) { console.log(JSON.stringify(fail(['usage:missing-input-filename']))); process.exit(0); }
let input;
try { input = JSON.parse(fs.readFileSync(file, 'utf8')); }
catch (error) { console.log(JSON.stringify(fail(['malformed-json:' + error.message]))); process.exit(0); }
const MAX = 1000000;
const integer = x => Number.isSafeInteger(x) && x >= 0 && x <= MAX;
const positiveInteger = x => integer(x) && x > 0;
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const reasons = [];
if (!object(input)) reasons.push('wrong-type:input');
if (object(input)) {
  if (!positiveInteger(input.replicas)) reasons.push('invalid:replicas');
  if (!positiveInteger(input.gpusPerReplica)) reasons.push('invalid:gpusPerReplica');
  if (!positiveInteger(input.capacityGpu)) reasons.push('invalid:capacityGpu');
  if (!positiveInteger(input.availableGPU)) reasons.push('invalid:availableGPU');
  if (!positiveInteger(input.perReplicaConcurrency)) reasons.push('invalid:perReplicaConcurrency');
  if (!integer(input.queuePerReplica)) reasons.push('invalid:queuePerReplica');
  if (!object(input.evidence)) reasons.push('wrong-type:evidence');
  else for (const key of ['artifactDigests', 'capacity', 'drain']) if (input.evidence[key] !== true) reasons.push('missing-evidence:' + key);
  if (!object(input.observed)) reasons.push('wrong-type:observed');
  else {
    if (!positiveInteger(input.observed.capacityGpu)) reasons.push('invalid:observed.capacityGpu');
    else if (input.observed.capacityGpu !== input.capacityGpu) reasons.push('changed:capacity');
    if (!positiveInteger(input.observed.availableGPU)) reasons.push('invalid:observed.availableGPU');
    else if (input.observed.availableGPU !== input.availableGPU) reasons.push('changed:availableGPU');
    if (input.observed.drainComplete !== true) reasons.push('failed:drain');
  }
  if (integer(input.capacityGpu) && integer(input.availableGPU) && input.availableGPU > input.capacityGpu) reasons.push('invalid:availableGPU-over-capacity');
  if (!reasons.length) {
    const requiredGPU = input.replicas * input.gpusPerReplica;
    const totalConcurrency = input.replicas * input.perReplicaConcurrency;
    const queueBound = input.replicas * input.queuePerReplica;
    if (!Number.isSafeInteger(requiredGPU) || requiredGPU > MAX) reasons.push('invalid:derived-requiredGPU');
    else if (requiredGPU > input.availableGPU) reasons.push('insufficient:GPU');
    if (!Number.isSafeInteger(totalConcurrency) || totalConcurrency > MAX) reasons.push('invalid:derived-totalConcurrency');
    if (!Number.isSafeInteger(queueBound) || queueBound > MAX) reasons.push('invalid:derived-queueBound');
    if (!reasons.length) console.log(JSON.stringify({ status: 'QUALIFY_FOR_REVIEW', derived: { requiredGPU, totalConcurrency, queueBound } }));
  }
}
if (reasons.length) console.log(JSON.stringify(fail(reasons)));

